{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Healthcare Research Data",
    "url": "http://localhost:7808",
    "widgets_json": {
      "trial_readout_form": {
        "name": "Trial Readout Form",
        "description": "Capture a clinical trial readout note.",
        "endpoint": "/trial-readout-form",
        "type": "table",
        "w": 20,
        "h": 10,
        "category": "Research",
        "params": [
          {
            "paramName": "ticker",
            "type": "text",
            "label": "Ticker",
            "value": "PFE"
          },
          {
            "paramName": "readout_date",
            "type": "date",
            "label": "Readout date",
            "value": "2026-08-19"
          },
          {
            "paramName": "save",
            "type": "button",
            "label": "Save"
          }
        ]
      },
      "trial_catalysts": {
        "name": "Trial Catalysts",
        "description": "Upcoming clinical trial readouts.",
        "endpoint": "/trial-catalysts",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "ticker",
            "type": "endpoint",
            "label": "Ticker",
            "optionsEndpoint": "/tickers",
            "value": "PFE"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "ticker",
              "headerName": "Ticker",
              "cellDataType": "text"
            },
            {
              "field": "phase",
              "headerName": "Phase",
              "cellDataType": "text"
            },
            {
              "field": "readout_date",
              "headerName": "Readout",
              "cellDataType": "dateString"
            }
          ]
        }
      },
      "catalyst_metric": {
        "name": "Catalysts 30d",
        "description": "Catalysts in the next 30 days.",
        "endpoint": "/catalyst-count",
        "type": "metric",
        "w": 6,
        "h": 4
      }
    },
    "apps_json": [
      {
        "name": "Trial Intake Room",
        "description": "Trial readouts and catalyst status.",
        "tabs": [
          {
            "tab_id": "intake",
            "name": "Intake",
            "layout": [
              {
                "i": "trial_readout_form",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 10
              },
              {
                "i": "catalyst_metric",
                "x": 20,
                "y": 0,
                "w": 8,
                "h": 6
              }
            ]
          },
          {
            "tab_id": "status",
            "name": "Status",
            "layout": [
              {
                "i": "trial_catalysts",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        ],
        "groups": [
          {
            "name": "Trial Sync",
            "type": "param",
            "paramName": "trial_ticker",
            "widgetIds": [
              "trial_readout_form",
              "trial_catalysts"
            ]
          }
        ]
      }
    ]
  }
}

